//! Source proxy domain-policy and model-allowlist fixtures. Native preparation
//! executes directly; live provider/model/quota repositories are explicitly absent.
use ai_platform_gateway::{migration_compat::{common::{CompatUser,CompatError},langgraph::LangGraphGovernance,langgraph_body},rate_limits::QuotaRpmLimiter};
use axum::{body::to_bytes,response::IntoResponse};
use serde_json::{Value,json};
use std::{sync::Arc,collections::HashMap};
fn user()->CompatUser{CompatUser{user_id:"user_1".into(),tenant_id:"tenant_1".into(),tier:"normal".into(),authenticated:true,request_id:"req-test-001".into(),..Default::default()}}
fn payload()->Value{json!({"input":{"messages":[{"role":"user","content":"hello"}]}})}
#[test] fn injects_domain_policy_for_langgraph_run(){let mut body=payload();langgraph_body::prepare_run_payload(&mut body,"threads/t1/runs/stream",&user(),&json!({"metadata":{"domain_policy":"agent"}}),None);assert_eq!(body["metadata"]["gateway"]["domain_policy"],"agent");assert_eq!(body["config"]["configurable"]["thread_id"],"t1");}
#[test] fn non_run_path_is_not_selected_for_preparation(){assert!(!langgraph_body::is_run_path("POST","assistants/search"));assert!(!langgraph_body::is_run_path("GET","threads/t1/runs/stream"));}
#[test] fn policy_none_does_not_inject_domain_metadata(){let mut body=payload();langgraph_body::prepare_run_payload(&mut body,"runs/wait",&user(),&json!({"metadata":{"domain_policy":"none"}}),None);assert!(body.get("metadata").is_none());}
#[test] fn preserves_existing_gateway_domain_policy(){let mut body=payload();body["metadata"]=json!({"gateway":{"domain_policy":"custom"}});langgraph_body::prepare_run_payload(&mut body,"runs/wait",&user(),&json!({"metadata":{"domain_policy":"agent"}}),None);assert_eq!(body["metadata"]["gateway"]["domain_policy"],"custom");}
#[test] fn root_runs_without_leading_slash_selected(){for path in ["runs","runs/stream","runs/wait","threads/t1/runs/stream"]{assert!(langgraph_body::is_run_path("POST",path));}}
#[test] fn browser_identity_and_gateway_model_are_replaced_by_authority(){let mut body=payload();body["config"]=json!({"configurable":{"user_id":"attacker","tenant_id":"foreign","checkpoint_ns":"foreign","gateway_model":{"api_key":"browser-secret"},"custom":"preserved"}});langgraph_body::prepare_run_payload(&mut body,"threads/t1/runs/wait",&user(),&json!({}),None);let config=&body["config"]["configurable"];assert_eq!(config["user_id"],"user_1");assert_eq!(config["tenant_id"],"tenant_1");assert_eq!(config["checkpoint_ns"],"tenant_1");assert_eq!(config["custom"],"preserved");assert!(!body.to_string().contains("browser-secret"));}
fn governance(allowed:Vec<&str>)->LangGraphGovernance{LangGraphGovernance{quota:None,rpm:Arc::new(QuotaRpmLimiter::default()),runtime_snapshot:None,live_resolution:None,live_services:None,services:HashMap::new(),allowed_models:allowed.into_iter().map(str::to_owned).collect(),quota_fail_closed:false,quota_alert_dedupe_ttl_seconds:60.0,security:None}}
#[tokio::test] async fn model_allowlist_matches_case_insensitive_prefix(){let mut body=payload();body["model"]=json!(" GPT-4o ");governance(vec!["gpt-*"]).prepare(&mut body,"runs/wait",&user(),None).await.unwrap();}
#[tokio::test] async fn model_allowlist_rejects_missing_or_nonmatching_model(){for model in ["","claude-3"]{let mut body=payload();body["model"]=json!(model);let error=governance(vec!["gpt-*"]).prepare(&mut body,"runs/wait",&user(),None).await.unwrap_err();assert_eq!(error.status,403);assert!(error.detail.as_str().unwrap().contains("not allowed for this API key"));}}
#[tokio::test] async fn retry_after_preserves_structured_error_response(){let mut error=CompatError::value(429,json!({"policy":"rate_limit","message":"quota exceeded"}));error.headers.insert("Retry-After".into(),"17".into());let response=error.into_response();assert_eq!(response.status(),429);assert_eq!(response.headers()["retry-after"],"17");let bytes=to_bytes(response.into_body(),4096).await.unwrap();let body:Value=serde_json::from_slice(&bytes).unwrap();assert_eq!(body["detail"]["policy"],"rate_limit");}
